mapper.select:
select notice.* from JGNotice notice
Join jguserinfo user ON notice.userCode= user.userCode

    JGNoticeDelect is null

        AND notice.JGNoticeText LIKE CONCAT('%', #{search}, '%')



        AND notice.JGNoticeProductTypeMajor = #{title1}



        AND notice.JGNoticeProductTypeMinor = #{title2}



        AND notice.JGNoticeProductTypeMinorList = #{title3}



        AND user.addressData = #{address1}



        AND user.addressDetailData = #{address2}



        AND CAST(REPLACE(notice.JGNoticeProductPrice, ',', '') AS UNSIGNED) >= #{price1}



        AND CAST(REPLACE(notice.JGNoticeProductPrice, ',', '') AS UNSIGNED) <= #{price2}


order by notice.JGNoticeCreate desc
limit #{cri.pageNum},#{cri.amount}

select count(*) from JGNotice notice
Join jguserinfo user ON notice.userCode= user.userCode

    JGNoticeDelect is null

        AND notice.JGNoticeText LIKE CONCAT('%', #{search}, '%')



        AND notice.JGNoticeProductTypeMajor = #{title1}



        AND notice.JGNoticeProductTypeMinor = #{title2}



        AND notice.JGNoticeProductTypeMinorList = #{title3}



        AND user.addressData = #{address1}



        AND user.addressDetailData = #{address2}



        AND CAST(REPLACE(notice.JGNoticeProductPrice, ',', '') AS UNSIGNED) >= #{price1}



        AND CAST(REPLACE(notice.JGNoticeProductPrice, ',', '') AS UNSIGNED) <= #{price2}

select notice.* from (
        select addressDetailData from jguserinfo
        where userCode = #{code}
    ) data
    join jguserinfo info On data.addressDetailData = info.addressDetailData
join jgnotice notice On info.userCode = notice.userCode
order by JGNoticeCreate desc
limit 0 ,12;
